// Assemble the /validate-token response from JWT check + DB rows.
const v = $('Verify JWT').first().json || {};
const claims = v.payload && typeof v.payload === 'object' ? v.payload : v;
const rows = $('Load Lead').all().map(i => i.json).filter(r => r && r.lead_id);

// Fail closed. Requiring a lead_id claim that MATCHES the row means a JWT
// node that errored (and passed through under continueRegularOutput) can
// never be mistaken for a successful verification.
if (v.error || !claims.lead_id || rows.length === 0 || claims.lead_id !== rows[0].lead_id) {
  return [{ json: { status: 'invalid' } }];
}

const r = rows[0];
const expired = r.revoked === true || new Date(r.tok_exp).getTime() < Date.now();
if (expired) {
  return [{ json: {
    status: 'expired',
    lead_id: r.lead_id,
    renewals_left: r.renewals_left ?? 0,
    language: r.language || 'en'
  }}];
}

const facts = {};
for (const i of $('Load Facts').all()) {
  if (i.json && i.json.key) facts[i.json.key] = i.json.value;
}

return [{ json: {
  status: 'valid',
  lead_id: r.lead_id,
  first_name: r.first_name,
  business_name: r.business_name,
  city: r.city,
  route: r.route,
  language: r.language || 'en',
  diagnosis_text: r.diagnosis_text,
  expires_at: r.tok_exp,
  renewals_left: r.renewals_left ?? 0,
  resume_position: r.resume_position || 0,
  video5_unlocked: !!r.video5_unlocked,
  facts
}}];
